<?php
namespace App\Http\Controllers;
use App\Models\{User,Owner};use Illuminate\Http\Request;use Illuminate\Support\Facades\{Auth,DB,Hash};use Illuminate\Support\Str;use Illuminate\Validation\Rules\Password;use Illuminate\Validation\ValidationException;
class AuthController extends Controller {
 public function me(Request $r){return response()->json(['csrf'=>csrf_token(),'realtime'=>['enabled'=>config('realtime.enabled')&&filled(config('realtime.key')),'key'=>config('realtime.key')],'user'=>$r->user()?array_merge($r->user()->only('id','name','email','phone','email_verified_at'),['platform_admin'=>$r->user() instanceof Owner&&(bool)$r->user()->platform_admin]):null,'portal'=>['kind'=>config('portal.kind'),'owner_signup'=>config('portal.kind')==='owner'&&config('portal.owner_registration')==='open','customer_url'=>config('portal.customer_url'),'owner_path'=>config('portal.kind')==='owner'?config('portal.owner_path'):null],'map'=>['tiles'=>config('encuentro.tile_url'),'attribution'=>config('encuentro.tile_attribution')]]);}
 public function register(Request $r){if(is_string($r->input('email')))$r->merge(['email'=>mb_strtolower(trim($r->input('email')))]);$d=$r->validate(['name'=>'required|string|min:2|max:100','email'=>['required','email','max:254',function($attribute,$value,$fail){if(User::whereRaw('LOWER(email) = ?',[$value])->exists())$fail('Este correo ya tiene una cuenta.');}],'password'=>['required','confirmed',Password::min(10)->letters()->numbers()],'phone'=>'nullable|string|max:30']);$u=User::create($d);Auth::guard('web')->login($u);$r->session()->regenerate();$r->session()->put('auth_password_version',$r->user()?->password_reset_at);try{app(\App\Services\EmailVerification::class)->send($r->user());}catch(\Throwable $e){\Illuminate\Support\Facades\Log::warning('Verificación pendiente de envío tras registro.');}return $this->me($r)->setStatusCode(201);}
 public function login(Request $r){return $this->authenticate($r,false);}
 private function authenticate(Request $r,bool $owner){$originalEmail=is_string($r->input('email'))?trim($r->input('email')):null;if(is_string($r->input('email')))$r->merge(['email'=>mb_strtolower(trim($r->input('email')))]);$d=$r->validate(['email'=>'required|email|max:254','password'=>'required|string|max:4096'],['email.required'=>'Escribe tu correo.','email.email'=>'Escribe un correo válido.','email.max'=>'El correo es demasiado largo.','password.required'=>'Escribe tu contraseña.','password.string'=>'La contraseña debe ser texto.','password.max'=>'La contraseña es demasiado larga.']);$attempts=app(\App\Services\LoginAttempts::class);if($blocked=$attempts->blocked($r))return $blocked;$email=$d['email'];$model=$owner?Owner::class:User::class;$matches=$model::whereRaw('LOWER(email) = ?',[$email])->pluck('email');if($matches->count()>1)$d['email']=$originalEmail;else $d['email']=fn($q)=>$q->whereRaw('LOWER(email) = ?',[$email]);if($owner)$d['activated']=true;else $d['account_type']='customer';if(!Auth::guard($owner?'owner':'web')->attempt($d)){$attempts->failed($r);throw ValidationException::withMessages(['email'=>'Correo o contraseña incorrectos.']);}$attempts->succeeded($r);$r->session()->regenerate();$r->session()->put('auth_password_version',$r->user()?->password_reset_at);return $this->me($r);}
 public function ownerLogin(Request $r){return $this->authenticate($r,true);}
 public function ownerRegister(Request $r){abort_unless(config('portal.owner_registration')==='open'||filled($r->input('invitation')),403,'El registro de propietarios requiere una invitación del administrador.');$d=$r->validate(['name'=>'required|string|min:2|max:100','email'=>'required|email|max:254','password'=>['required','confirmed',Password::min(12)->letters()->numbers()],'invitation'=>'nullable|string|size:64']);$o=DB::transaction(function()use($d){if(empty($d['invitation'])){abort_if(Owner::where('email',mb_strtolower($d['email']))->exists(),422,'Este correo ya tiene una cuenta de propietario. Inicia sesión o utiliza su invitación de activación.');$u=User::create(['name'=>$d['name'],'email'=>'owner-'.Str::uuid().'@internal.invalid','password'=>Str::random(64)]);$u->forceFill(['account_type'=>'internal_owner'])->save();return Owner::create(['user_id'=>$u->id,'name'=>$d['name'],'email'=>mb_strtolower($d['email']),'password'=>$d['password'],'activated'=>true]);}$i=DB::table('owner_invitations')->where('token_hash',hash('sha256',$d['invitation']))->lockForUpdate()->first();abort_unless($i&&$i->email===mb_strtolower($d['email'])&&!$i->used_at&&now()->lt($i->expires_at),422,'La invitación no es válida, ya fue utilizada o ha vencido.');$o=Owner::where('email',$i->email)->first();abort_if($o?->activated,422,'Esta cuenta de propietario ya está activada.');if(!$o){$u=User::create(['name'=>$d['name'],'email'=>'owner-'.Str::uuid().'@internal.invalid','password'=>Str::random(64)]);$u->forceFill(['account_type'=>'internal_owner'])->save();$o=new Owner(['user_id'=>$u->id,'email'=>$i->email]);}$o->fill(['name'=>$d['name'],'password'=>$d['password'],'activated'=>true])->save();DB::table('owner_invitations')->where('id',$i->id)->update(['used_at'=>now()]);return $o;},3);Auth::guard('owner')->login($o);$r->session()->regenerate();$r->session()->put('auth_password_version',$r->user()?->password_reset_at);try{app(\App\Services\EmailVerification::class)->send($r->user());}catch(\Throwable $e){\Illuminate\Support\Facades\Log::warning('Verificación pendiente de envío tras registro.');}return $this->me($r)->setStatusCode(201);}
 public function logout(Request $r){Auth::guard(config('portal.kind')==='owner'?'owner':'web')->logout();$r->session()->invalidate();$r->session()->regenerateToken();return response()->json(['ok'=>true,'csrf'=>csrf_token()]);}
}
